/* Chem-aware DreaMS — static platform renderer.
 *
 * Everything on this page is precomputed. The single data source is
 * `data/showcase.json`, generated by `tasks/make_hf_showcase.py` from the real
 * MTBLS13729 smoke results. No compute happens in the browser.
 */
"use strict";

const $ = (sel) => document.querySelector(sel);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

const fmt = (n, d = 4) => (n === null || n === undefined) ? "—" : Number(n).toFixed(d);
const pct = (n, d = 2) => (n === null || n === undefined) ? "—" : (Number(n) * 100).toFixed(d) + "%";

const SCHYMANSKI = {
  1: "confirmed structure (reference standard)",
  2: "probable structure (library match)",
  3: "tentative candidate(s)",
  4: "unequivocal molecular formula",
  5: "exact mass only",
};
const levelTag = (lv) => `<span class="tag l${lv}">L${lv}</span>`;

let DATA = null;

/* ---------------------------------------------------------------- */
async function boot() {
  try {
    const res = await fetch("data/showcase.json");
    DATA = await res.json();
  } catch (err) {
    document.body.innerHTML = `<div style="padding:40px;color:#c62828">Failed to load showcase data: ${esc(err.message)}</div>`;
    return;
  }
  renderOverview();
  renderLadder();
  renderMatches();
  renderFDR();
  renderCosmic();
  renderRules();
  renderExplain();
  renderHMDB();
  renderDiff();
  renderNovel();
  renderAuthor();
  renderCitations();
  wireRunForm();
  wireNav();
}

/* ---------------------------------------------------------------- */
function renderOverview() {
  const o = DATA.overview;
  const stats = [
    ["Query spectra", o.n_queries.toLocaleString(), "MTBLS13729 smoke"],
    ["Library spectra", DATA.report_ladder.n_library_spectra.toLocaleString(), "MONA pos subset"],
    ["Confident matches", o.n_confident, "cos ≥ 0.7 ∧ Δm/z ≤ 20 ppm"],
    ["Distinct structures", o.n_distinct_confident_inchikey, "unique InChIKey"],
    ["Confident rate", pct(o.confident_rate, 3), "of top-1 hits"],
    ["Self-retrieval FDR", DATA.cosmic_probe.self_retrieval_fdr.mz_constrained + "%", "m/z-constrained truth"],
  ];
  $("#overview-stats").innerHTML = stats.map(([k, v, sub]) =>
    `<div class="stat"><div class="v">${v}</div><div class="k">${k}</div><div class="sub">${sub}</div></div>`
  ).join("");
}

function renderLadder() {
  const cos = DATA.report_ladder.annotation_rate_cosine_only;
  const mz = DATA.report_ladder.annotation_rate_cosine_and_mz;
  const keys = Object.keys(cos).sort();
  const max = Math.max(...keys.map((k) => Math.max(cos[k], mz[k])));
  const row = (label, obj, cls) => {
    const bars = keys.map((k) =>
      `<div class="bar ${cls}" style="height:${(obj[k] / max) * 100}%" title="${k} → ${pct(obj[k])}"><span>${pct(obj[k])}</span></div>`
    ).join("");
    return `<div class="ladder-row"><div class="label">${label}</div><div class="bars">${bars}</div></div>`;
  };
  $("#ladder").innerHTML =
    `<h3>Annotation rate ladder (threshold → fraction annotated)</h3>` +
    `<div class="ladder-row" style="margin-bottom:2px"><div class="label" style="color:#9aa4b5">cosine threshold</div>` +
    `<div class="bars" style="height:16px">${keys.map((k) => `<div style="flex:1;text-align:center;font-size:10px;color:#9aa4b5">${k}</div>`).join("")}</div></div>` +
    row("cosine only", cos, "cosine") +
    row("cosine + m/z", mz, "mz") +
    `<p class="lede" style="margin-top:12px">The m/z hard constraint cuts ~4× over-annotation at every threshold (blue vs grey).</p>`;
}

/* ---------------------------------------------------------------- */
function renderMatches() {
  const cols = [
    ["file", "File", (r) => r.query_file],
    ["scan", "Scan", (r) => r.query_scan, (r) => r.query_scan],
    ["mz", "Prec. m/z", (r) => fmt(r.query_precursor_mz), (r) => r.query_precursor_mz],
    ["cos", "Cosine", (r) => fmt(r.cosine), (r) => r.cosine],
    ["dppm", "Δppm", (r) => fmt(r.dppm, 2), (r) => r.dppm],
    ["name", "Name", (r) => r.lib_name],
    ["inchikey", "InChIKey", (r) => `<span class="mono">${esc(r.lib_inchikey)}</span>`],
    ["lvl", "Level", (r) => levelTag(r.schymanski_level), (r) => r.schymanski_level],
  ];
  $("#matches-table").innerHTML = buildTable(cols, DATA.confident_matches);
}

const NUM_KEYS = new Set(["mz", "cos", "dppm", "scan", "lvl", "tumor", "normal", "or", "p", "q", "n", "author", "ours", "novel", "ambiguous", "resolved"]);
const cellCls = (k) => (NUM_KEYS.has(k) ? "num" : "");

function buildTable(cols, rows) {
  // cols: [key, label, renderFn, rawFn(optional)]. rawFn is used for sorting;
  // when omitted, sort on the rendered text with tags stripped.
  let sorted = rows.slice();
  let state = { key: null, dir: 1 };

  const head = cols.map(([k, label]) =>
    `<th data-k="${k}" class="${cellCls(k)}">${label}</th>`).join("");
  const body = () => sorted.map((r) =>
    `<tr>${cols.map(([k, , f]) => `<td class="${cellCls(k)}">${f(r)}</td>`).join("")}</tr>`).join("");

  const table = document.createElement("table");
  table.className = "data-table";
  table.innerHTML = `<thead><tr>${head}</tr></thead><tbody>${body()}</tbody>`;

  table.querySelectorAll("th").forEach((th) => {
    th.addEventListener("click", () => {
      const k = th.dataset.k;
      const col = cols.find((c) => c[0] === k);
      const raw = col[3] || ((r) => String(col[2](r)).replace(/<[^>]*>/g, ""));
      if (state.key === k) state.dir *= -1; else { state.key = k; state.dir = 1; }
      sorted = sorted.slice().sort((a, b) => {
        const x = raw(a), y = raw(b);
        const cmp = (typeof x === "number" && typeof y === "number")
          ? x - y : String(x).localeCompare(String(y));
        return cmp * state.dir;
      });
      table.querySelector("tbody").innerHTML = body();
    });
  });
  return table.outerHTML;
}

/* ---------------------------------------------------------------- */
function renderFDR() {
  const f = DATA.overview.fdr;
  const s = DATA.cosmic_probe.self_retrieval_fdr;
  $("#fdr-body").innerHTML = `
    <div class="card">
      <h4>Target-decoy q-value (smoke run)</h4>
      <div class="big">q&nbsp;median ${fmt(f.q_median)}</div>
      <div class="dim">${f.n_fdr_pass} / ${f.n_top1} top-1 hits pass q ≤ 0.05</div>
      <div class="dim" style="margin-top:8px">median q ${fmt(f.q_median)}, min ${fmt(f.q_min)}</div>
    </div>
    <div class="card note">
      <h4>⚠ Decoys do not compete on the smoke library</h4>
      <div class="dim">With a 1,000-spectrum library the target-decoy q-value collapses to a
        flat minimum — it is <strong>not</strong> a meaningful 100%-confident claim. The reliable
        confidence scale is the <strong>self-retrieval ground-truth FDR</strong> (right).</div>
    </div>
    <div class="card">
      <h4>Self-retrieval truth FDR</h4>
      <div class="big">${s.mz_constrained}%</div>
      <div class="dim">m/z-constrained (MassSpecGym)</div>
      <div class="big" style="margin-top:10px">${s.cosine_only}%</div>
      <div class="dim">cosine-only (no m/z constraint)</div>
    </div>
    <div class="card">
      <h4>Method</h4>
      <div class="dim">Target-decoy FDR (Elias &amp; Gygi 2007; Scheubert et al. 2017), q-value
        (Benjamini–Hochberg). Confidence = 1 − FDR.</div>
    </div>`;
}

/* ---------------------------------------------------------------- */
function renderCosmic() {
  const c = DATA.cosmic_probe;
  $("#cosmic-body").innerHTML = `
    <div class="card">
      <h4>Frozen concept probe</h4>
      <div class="big">${c.n_rules} rules</div>
      <div class="dim">${c.probe_train.n_molecules} train / ${c.probe_val.n_molecules} val / ${c.probe_test.n_molecules} test molecules</div>
    </div>
    <div class="card">
      <h4>Probe test AUPRC</h4>
      <div class="big">${c.probe_test.auprc}</div>
      <div class="dim">vs baseline ${c.probe_test.baseline_auprc} — rules are decodable from the embedding</div>
    </div>
    <div class="card null">
      <h4>Structure-space decoy coherence</h4>
      <div class="big">P = ${c.coherence_decoy.p_value}</div>
      <div class="dim">${esc(c.coherence_decoy.verdict)}</div>
      <div class="dim" style="margin-top:8px">${esc(c.coherence_decoy.note)}</div>
    </div>
    <div class="card note">
      <h4>Verdict</h4>
      <div class="dim">COSMIC coherence = <strong>self-consistency</strong>, not confidence.
        Confidence is the FDR panel. The interface is reserved; it must never be read as P(correct).</div>
    </div>`;
}

/* ---------------------------------------------------------------- */
function renderRules() {
  const c = DATA.cosmic_probe;
  $("#rules-body").innerHTML = `
    <div class="card">
      <h4>Rule library</h4>
      <div class="big">${c.n_rules} / 335</div>
      <div class="dim">Schymanski chemical rules decoded (frozen concept probe over the DreaMS retrieval embedding).</div>
    </div>
    <div class="card">
      <h4>Per-match rule evidence</h4>
      <div class="dim">Rule matching is evaluated per annotation (substructure / formula evidence), not as a global
        confidence boost. Semantic upgrade only — a rule hit upgrades the Schymanski level
        interpretation, it does <strong>not</strong> by itself predict correctness.</div>
    </div>
    <div class="card note">
      <h4>Scope</h4>
      <div class="dim">335 main rules only; the rule library is <strong>not</strong> expanded beyond this
        (project discipline). Full per-rule hit table is emitted by the pipeline and rendered here in the
        full build.</div>
    </div>`;
}

/* ---------------------------------------------------------------- */
function renderExplain() {
  const items = DATA.confident_matches.map((r) => {
    const chain = [
      ["Cosine similarity", `${fmt(r.cosine)} ≥ 0.7`, r.cosine >= 0.7],
      ["Precursor m/z", `${r.query_precursor_mz} vs lib ${r.lib_precursor_mz}`, true],
      ["Δppm", `${fmt(r.dppm, 2)} ≤ 20 ppm`, Math.abs(r.dppm) <= 20],
      ["Schymanski level", `L${r.schymanski_level} — ${SCHYMANSKI[r.schymanski_level]}`, true],
      ["Structure", `<span class="smiles">${esc(r.lib_smiles)}</span>`, true],
      ["InChIKey", `<span class="mono">${esc(r.lib_inchikey)}</span>`, true],
    ];
    const ev = chain.map(([k, v, ok]) =>
      `<li><span class="k">${k}</span><span class="v">${ok ? "✓ " : "✗ "}${v}</span></li>`
    ).join("");
    return `
      <div class="explain-item">
        <div class="explain-head" data-toggle>
          <div><span class="name">${esc(r.lib_name)}</span>
            <span class="meta"> · ${esc(r.query_file)} scan ${r.query_scan} · cos ${fmt(r.cosine)}</span></div>
          <span>▸</span>
        </div>
        <div class="explain-body" hidden><ul class="evidence">${ev}</ul></div>
      </div>`;
  }).join("");
  $("#explain-body").innerHTML = items;
  $("#explain-body").querySelectorAll("[data-toggle]").forEach((h) => {
    h.addEventListener("click", () => {
      const body = h.nextElementSibling;
      body.hidden = !body.hidden;
      h.querySelector("span:last-child").textContent = body.hidden ? "▸" : "▾";
    });
  });
}

/* ---------------------------------------------------------------- */
function renderHMDB() {
  $("#hmdb-body").innerHTML = `
    <div class="big">No biochemical confidence yet</div>
    <div style="margin-top:8px">HMDB pathway / disease association fields are reserved and
    currently <code>NaN</code> for every match. This panel will render HMDB ID, pathway,
    and functional category once populated.</div>`;
}

/* ---------------------------------------------------------------- */
function renderDiff() {
  const cols = [
    ["name", "Name", (r) => r.lib_name],
    ["tumor", "Spectra (tumor)", (r) => r.n_spectra_tumor, (r) => r.n_spectra_tumor],
    ["normal", "Spectra (normal)", (r) => r.n_spectra_normal, (r) => r.n_spectra_normal],
    ["or", "Odds ratio", (r) => r.odds_ratio === null ? "—" : fmt(r.odds_ratio, 2), (r) => r.odds_ratio],
    ["p", "p-value", (r) => fmt(r.p_value, 4), (r) => r.p_value],
    ["q", "q-value", (r) => fmt(r.q_value, 4), (r) => r.q_value],
  ];
  $("#diff-table").innerHTML = buildTable(cols, DATA.differential_analysis) +
    `<p class="lede" style="margin-top:10px">No structure reaches q &lt; 0.05 — expected on the smoke run
    (too few confident matches for statistical power).</p>`;
}

/* ---------------------------------------------------------------- */
function renderNovel() {
  const cols = [
    ["name", "Name", (r) => r.lib_name],
    ["inchikey", "InChIKey", (r) => `<span class="mono">${esc(r.lib_inchikey)}</span>`],
    ["mz", "Median m/z", (r) => r.median_mz, (r) => r.median_mz],
    ["n", "N spectra", (r) => r.n_spectra, (r) => r.n_spectra],
    ["dppm", "Min Δppm to author", (r) => fmt(r.min_dppm_to_author, 0), (r) => r.min_dppm_to_author],
  ];
  $("#novel-table").innerHTML = buildTable(cols, DATA.novel_findings);
}

/* ---------------------------------------------------------------- */
